import{_ as t}from"./chunks/event-check-review-expanded.Cla9_XDx.js";import{c as s,Q as a,j as o,m as n}from"./chunks/framework.BqPkuuVc.js";const r="/assets/event-check-menu.aOqTsVcZ.png",i="/assets/event-check-review.BUiYDPiF.png",c="/assets/event-check-all-clear.Dn5_k_F0.png",h="/assets/event-check-finding-noCourses.NUe0HPez.png",l="/assets/event-check-finding-noClasses.K8WTnTcb.png",d="/assets/event-check-finding-classesWithoutCourses.DgwDqhjG.png",m="/assets/event-check-finding-multiPartClassesUnscorable.CIaRKWg2.png",p="/assets/event-check-finding-competitorsWithoutClass.DWITV8kR.png",u="/assets/event-check-finding-noCompetitors.D7MU66tK.png",g="/assets/event-check-finding-coursePools.BqWx276Z.png",b="/assets/event-check-finding-coursesWithoutControls.Du3nhSNb.png",f="/assets/event-check-finding-competitorsWithoutName.C47Dl1wH.png",w="/assets/event-check-finding-cardSharedOnCourse.F71jFtJJ.png",y="/assets/event-check-finding-duplicateBibs.CFeY-IsK.png",v="/assets/event-check-finding-emptyClassesWithoutCourses.2R5HXyxw.png",k="/assets/event-check-finding-competitorsWithoutCard.BoJmQZnL.png",_="/assets/event-check-finding-duplicateCardNumbers.BPgYepu0.png",x="/assets/event-check-finding-possibleDuplicateEntries.CpMv3i6b.png",A="/assets/event-check-finding-incompleteTeams.BnZb2dce.png",q="/assets/event-check-finding-teamClassCompetitorsWithoutTeam.CXINJ7MJ.png",C="/assets/event-check-finding-competitorsWithoutStartTime.B2vHv6KT.png",P="/assets/event-check-finding-startConflicts.BlEeC9EX.png",W="/assets/event-check-finding-emptyClasses.DH2UzvxE.png",S="/assets/event-check-finding-unusedCourses.BftLWa5U.png",T="/assets/event-check-finding-competitorsWithIncompleteName.BH_m8eWa.png",I="/assets/event-check-finding-competitorsWithoutClub.BHCFxc0q.png",H="/assets/event-check-finding-sharedNames.u1R_bci2.png",J=JSON.parse('{"title":"The event check","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/event-check.md","filePath":"user/running-the-event/event-check.md"}'),E={name:"user/running-the-event/event-check.md"};function B(N,e,O,R,D,F){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="the-event-check" tabindex="-1">The event check <a class="header-anchor" href="#the-event-check" aria-label="Permalink to &quot;The event check&quot;">​</a></h1><p><strong>Check event</strong> looks through the event for what is likely to go wrong on the day: a class nobody can be scored in, two runners on one card, a runner with no card. It changes nothing; it tells you what it found, and lets you fix each thing from where you are.</p><p>This page shows every problem the check can report, what it means, and how to fix it.</p><h2 id="running-the-check" tabindex="-1">Running the check <a class="header-anchor" href="#running-the-check" aria-label="Permalink to &quot;Running the check&quot;">​</a></h2><p>Open the state menu (the <strong>Setup</strong>, <strong>Live</strong> or <strong>Finished</strong> button at the right of the app bar) and click <strong>Check event</strong>. It is there in every state, so you can run it while you set up, during the race as late entries arrive, or afterwards.</p><p><img src="'+r+'" alt="The state menu open with Check event just above Events"></p><p><strong>Start event</strong> runs the same check first. If it finds anything above <strong>Info</strong>, <strong>Before you start</strong> lists it, and you can <strong>Start anyway</strong> or <strong>Cancel</strong> and fix it first. Info alone never stops a start.</p><h2 id="reading-the-report" tabindex="-1">Reading the report <a class="header-anchor" href="#reading-the-report" aria-label="Permalink to &quot;Reading the report&quot;">​</a></h2><p>The report has a section for each grade, most severe first:</p><ul><li><strong>Critical</strong> — results will be wrong or missing for somebody unless it is fixed.</li><li><strong>Serious</strong> — very likely to cause trouble on the day.</li><li><strong>Warning</strong> — worth a look; often fine, sometimes a mistake.</li><li><strong>Info</strong> — tidy-up, and things worth knowing.</li></ul><p><img src="'+i+'" alt="The Event check dialog: Critical, Serious, Warning and Info sections, one line per problem"></p><p>Each problem is one line. Click it to open it: it lists up to 25 of the competitors, classes, courses or teams it is about. Duplicates are gathered under what they share — the card number, the bib, the name — and beside each name is what tells them apart, such as a competitor&#39;s class, course and start time.</p><p><img src="'+t+'" alt="A card two competitors are out on at once, opened: Peter Anderson and Tom Price under card 98765, each with their class, course and start time"></p><p><strong>Click a name to fix it there and then.</strong> A competitor opens <strong>Edit competitor</strong>; a class, course or team opens its own edit dialog. The report stays open behind it, and runs again when you save. A problem with nothing to list — no courses, classes or competitors at all — has a <strong>Go to</strong> link to the screen where you add them instead.</p><p>Competitors who are <strong>DNS</strong>, <strong>Not participating</strong> or <strong>Cancelled</strong> are left out of the card, start, duplicate and team checks: a withdrawn runner sharing a card is nobody&#39;s problem.</p><p>The check doesn&#39;t look at your map or your radio controls. When it finds nothing, it says <strong>No problems found</strong>.</p><p><img src="'+c+'" alt="The Event check dialog saying No problems found"></p><p>If the check itself fails, the dialog says <strong>The event could not be checked</strong> rather than showing an all clear. Click <strong>Check again</strong>. If Start event couldn&#39;t run the check, a message says so and the event starts anyway.</p><h2 id="critical" tabindex="-1">Critical <a class="header-anchor" href="#critical" aria-label="Permalink to &quot;Critical&quot;">​</a></h2><h3 id="no-courses-have-been-created" tabindex="-1">No courses have been created <a class="header-anchor" href="#no-courses-have-been-created" aria-label="Permalink to &quot;No courses have been created&quot;">​</a></h3><p><img src="'+h+'" alt="No courses have been created, opened to a Go to courses link"></p><p><strong>What it means:</strong> the event has no courses, so nobody can be scored.</p><p><strong>How to fix it:</strong> click <strong>Go to courses</strong>, then import your courses from Purple Pen, OCAD or Condes, or add them by hand. See <a href="./../event-setup/import-event-data">Importing event data</a> and <a href="./../event-setup/classes-and-courses#creating-a-course-by-hand">Creating a course by hand</a>.</p><h3 id="no-classes-have-been-created" tabindex="-1">No classes have been created <a class="header-anchor" href="#no-classes-have-been-created" aria-label="Permalink to &quot;No classes have been created&quot;">​</a></h3><p><img src="'+l+'" alt="No classes have been created, opened to a Go to classes link"></p><p><strong>What it means:</strong> the event has no classes, so no competitor can be placed or given a course.</p><p><strong>How to fix it:</strong> click <strong>Go to classes</strong>, then import classes, create them by hand, or create one per course. See <a href="./../event-setup/classes-and-courses#creating-a-class-by-hand">Creating a class by hand</a> and <a href="./../event-setup/classes-and-courses#auto-creating-classes-from-courses">Auto-creating classes from courses</a>.</p><h3 id="a-class-with-competitors-has-no-course" tabindex="-1">A class with competitors has no course <a class="header-anchor" href="#a-class-with-competitors-has-no-course" aria-label="Permalink to &quot;A class with competitors has no course&quot;">​</a></h3><p><img src="'+d+'" alt="A class with competitors has no course, opened to the class Open"></p><p><strong>What it means:</strong> people are entered in the class, but it has no course. Their cards can&#39;t be checked, so none of them will get a result.</p><p><strong>How to fix it:</strong> click the class, and in <strong>Edit class</strong> give it its course. See <a href="./../event-setup/classes-and-courses#assigning-courses-to-classes">Assigning courses to classes</a>. If the class shouldn&#39;t exist, move its competitors to the right class first.</p><h3 id="a-multi-part-class-s-courses-and-changeovers-don-t-match" tabindex="-1">A multi-part class&#39;s courses and changeovers don&#39;t match <a class="header-anchor" href="#a-multi-part-class-s-courses-and-changeovers-don-t-match" aria-label="Permalink to &quot;A multi-part class&#39;s courses and changeovers don&#39;t match&quot;">​</a></h3><p><img src="'+m+'" alt="A multi-part class&#39;s courses and changeovers don&#39;t match, opened to Ride and Run with its one remaining course, Ride"></p><p><strong>What it means:</strong> the class runs several courses one after another on one card, and its list of courses no longer agrees with its changeovers — usually because one of the courses was deleted. Until it&#39;s fixed, everyone in the class is scored as a missing punch. Beside the class are the courses it has now.</p><p><strong>How to fix it:</strong> click the class. In <strong>Edit class</strong>, put back the missing course, or set a changeover for each boundary between the courses that are there. See <a href="./../event-setup/classes-and-courses#classes-whose-competitors-do-every-course">Classes whose competitors do every course</a>.</p><h3 id="a-competitor-has-no-class" tabindex="-1">A competitor has no class <a class="header-anchor" href="#a-competitor-has-no-class" aria-label="Permalink to &quot;A competitor has no class&quot;">​</a></h3><p><img src="'+p+'" alt="A competitor has no class, opened to Tia Temple with her club"></p><p><strong>What it means:</strong> the competitor isn&#39;t in any class — usually because their class was deleted. They can&#39;t be scored or placed. Their club is shown beside their name, to help you work out where they belong.</p><p><strong>How to fix it:</strong> click the competitor and choose their <strong>Class</strong> in <strong>Edit competitor</strong>.</p><h2 id="serious" tabindex="-1">Serious <a class="header-anchor" href="#serious" aria-label="Permalink to &quot;Serious&quot;">​</a></h2><h3 id="no-competitors-have-been-added" tabindex="-1">No competitors have been added <a class="header-anchor" href="#no-competitors-have-been-added" aria-label="Permalink to &quot;No competitors have been added&quot;">​</a></h3><p><img src="'+u+'" alt="No competitors have been added, opened to a Go to competitors link"></p><p><strong>What it means:</strong> nobody is entered yet. Fine while you set up, but an event started like this only has the competitors you add on the day.</p><p><strong>How to fix it:</strong> click <strong>Go to competitors</strong>, then import the entries or add competitors. See <a href="./../event-setup/import-event-data">Importing event data</a>, or <a href="./late-entries">Late entries</a> for adding them on the day.</p><h3 id="a-class-has-more-than-one-course-which-a-scatter-or-score-event-cannot-choose-between" tabindex="-1">A class has more than one course, which a scatter or score event cannot choose between <a class="header-anchor" href="#a-class-has-more-than-one-course-which-a-scatter-or-score-event-cannot-choose-between" aria-label="Permalink to &quot;A class has more than one course, which a scatter or score event cannot choose between&quot;">​</a></h3><p><img src="'+g+'" alt="A class has more than one course, opened to Open Score with its courses Long and Score 60"></p><p><strong>What it means:</strong> the class has a pool of courses, and one of them is a score or scatter course. Manager picks a pool member by matching a card&#39;s punches to a course, which can&#39;t be done when a course has no fixed order. Beside the class are its courses.</p><p><strong>How to fix it:</strong> click the class and give it one course. If its competitors run all its courses one after another, set <strong>Competitors do</strong> to <strong>All courses</strong> instead. See <a href="./../event-setup/classes-and-courses#score-and-scatter-courses">Score and scatter courses</a> and <a href="./../event-setup/classes-and-courses#course-pools-and-locking-a-competitor-to-a-course">Course pools</a>.</p><h3 id="a-course-in-use-has-no-controls" tabindex="-1">A course in use has no controls <a class="header-anchor" href="#a-course-in-use-has-no-controls" aria-label="Permalink to &quot;A course in use has no controls&quot;">​</a></h3><p><img src="'+b+'" alt="A course in use has no controls, opened to Course 7 with the classes that use it, M Open and W Open"></p><p><strong>What it means:</strong> a class runs this course, but it has no controls. Every card read against it is judged against an empty course. Beside the course are the classes that use it.</p><p><strong>How to fix it:</strong> click the course and add its controls on the <strong>Controls</strong> tab of <strong>Edit course</strong>, or re-import the course file. If the classes should run a different course, change their course instead.</p><h3 id="a-competitor-has-no-name" tabindex="-1">A competitor has no name <a class="header-anchor" href="#a-competitor-has-no-name" aria-label="Permalink to &quot;A competitor has no name&quot;">​</a></h3><p><img src="'+f+'" alt="A competitor has no name, opened to an entry shown by its card number 8004321, in M21E"></p><p><strong>What it means:</strong> the entry has neither a given nor a family name — often a card downloaded before anyone said who carried it, which is shown by its card number. Results, start lists and screens show a blank.</p><p><strong>How to fix it:</strong> click it and fill in the name. If nobody knows whose card it is, see <a href="./card-download#fast-fixes-right-after-a-download">Unknown cards</a>.</p><h3 id="a-competitor-is-out-on-course-at-the-same-time-as-someone-else-on-the-same-card" tabindex="-1">A competitor is out on course at the same time as someone else on the same card <a class="header-anchor" href="#a-competitor-is-out-on-course-at-the-same-time-as-someone-else-on-the-same-card" aria-label="Permalink to &quot;A competitor is out on course at the same time as someone else on the same card&quot;">​</a></h3><p><img src="'+w+'" alt="Out on course on the same card, opened to card 98765 with Peter Anderson and Tom Price, each with class, course and start time"></p><p><strong>What it means:</strong> two or more competitors on one card have both started (are in the forest, or have checked in) and neither has downloaded. Only one of them can really have the card, and the download will go to only one of them. Each is shown with their class, course and start time, so you can tell who has it.</p><p><strong>How to fix it:</strong> find out who is carrying the card, then click the others and correct their <strong>Card number</strong>. See <a href="./resolving-issues#lost-cards-and-shared-cards">Lost cards and shared cards</a>.</p><h3 id="an-entry-shares-a-bib-number-with-another" tabindex="-1">An entry shares a bib number with another <a class="header-anchor" href="#an-entry-shares-a-bib-number-with-another" aria-label="Permalink to &quot;An entry shares a bib number with another&quot;">​</a></h3><p><img src="'+y+'" alt="An entry shares a bib number, opened to bib 12 with Emma Clarke and Oli Owen, each with class and course"></p><p><strong>What it means:</strong> two entries wear the same bib. Relay teams are compared as teams. Anyone reading a bib off a runner — at the finish, on the commentary — will find two people.</p><p><strong>How to fix it:</strong> click one of them and give it another bib number, or renumber the classes with <a href="./../event-setup/bib-numbers">Bib numbers</a>.</p><h2 id="warning" tabindex="-1">Warning <a class="header-anchor" href="#warning" aria-label="Permalink to &quot;Warning&quot;">​</a></h2><h3 id="a-class-nobody-is-entered-in-yet-has-no-course" tabindex="-1">A class nobody is entered in yet has no course <a class="header-anchor" href="#a-class-nobody-is-entered-in-yet-has-no-course" aria-label="Permalink to &quot;A class nobody is entered in yet has no course&quot;">​</a></h3><p><img src="'+v+'" alt="A class nobody is entered in yet has no course, opened to Late Entries"></p><p><strong>What it means:</strong> the class is empty now, but a late entry into it couldn&#39;t be scored.</p><p><strong>How to fix it:</strong> click the class and give it a course, or delete it if it isn&#39;t needed.</p><h3 id="competitors-without-a-card-number" tabindex="-1">Competitors without a card number <a class="header-anchor" href="#competitors-without-a-card-number" aria-label="Permalink to &quot;Competitors without a card number&quot;">​</a></h3><p><img src="'+k+'" alt="Competitors without a card number, opened to three competitors with their class and start time"></p><p><strong>What it means:</strong> these competitors have no card number yet. Often fine — hire cards are commonly handed out at the start — but a download can&#39;t find them until they have one. Beside each is their class and start time, so you can see who is due out first.</p><p><strong>How to fix it:</strong> click a competitor and enter their <strong>Card number</strong> when you know it. If they download first, the read waits as an <strong>Unknown card</strong> until you assign it. See <a href="./../event-setup/competitors-clubs-teams#card-numbers">Card numbers</a>.</p><h3 id="a-competitor-shares-a-card-number-with-someone-else" tabindex="-1">A competitor shares a card number with someone else <a class="header-anchor" href="#a-competitor-shares-a-card-number-with-someone-else" aria-label="Permalink to &quot;A competitor shares a card number with someone else&quot;">​</a></h3><p><img src="'+_+'" alt="A competitor shares a card number, opened to card 2104455 with Ivy Irwin and Jon Irwin, each with class, course and start time"></p><p><strong>What it means:</strong> more than one competitor who hasn&#39;t downloaded yet has this card number, and at most one of them has started. That is normal for a card handed on — a family sharing one card, a hire card going out twice — since each download goes to the next person on the card who hasn&#39;t downloaded. Once a runner has downloaded they drop out of this check. It&#39;s a mistake if they will be out at the same time; check their start times.</p><p><strong>How to fix it:</strong> if it&#39;s intended, nothing. If not, click the competitor with the wrong number and correct it. Once two of them are on the course at once, this becomes the Serious <a href="#a-competitor-is-out-on-course-at-the-same-time-as-someone-else-on-the-same-card">out on course on the same card</a>.</p><h3 id="a-competitor-may-be-entered-twice-same-name-same-club" tabindex="-1">A competitor may be entered twice: same name, same club <a class="header-anchor" href="#a-competitor-may-be-entered-twice-same-name-same-club" aria-label="Permalink to &quot;A competitor may be entered twice: same name, same club&quot;">​</a></h3><p><img src="'+x+'" alt="A competitor may be entered twice, opened to two Sara Holm entries with class, course and start time"></p><p><strong>What it means:</strong> two entries have the same name and the same club (ignoring capitals and spaces). Usually one person entered twice; sometimes two people with one name. Beside each is their class, course, start time and status, to help you decide which to keep.</p><p><strong>How to fix it:</strong> click the entry that shouldn&#39;t be there and delete it in <strong>Edit competitor</strong>, or, if they are two people, leave them.</p><h3 id="a-team-is-missing-a-runner-on-at-least-one-leg" tabindex="-1">A team is missing a runner on at least one leg <a class="header-anchor" href="#a-team-is-missing-a-runner-on-at-least-one-leg" aria-label="Permalink to &quot;A team is missing a runner on at least one leg&quot;">​</a></h3><p><img src="'+A+'" alt="A team is missing a runner, opened to Bushwalkers 1 with its class and club"></p><p><strong>What it means:</strong> a relay team has an empty leg. Shown with its class and club.</p><p><strong>How to fix it:</strong> click the team and put a runner on each leg in <strong>Edit team</strong>. See <a href="./../event-setup/relay-events#building-teams-by-hand">Building teams</a>.</p><h3 id="a-competitor-in-a-relay-class-is-not-on-a-team" tabindex="-1">A competitor in a relay class is not on a team <a class="header-anchor" href="#a-competitor-in-a-relay-class-is-not-on-a-team" aria-label="Permalink to &quot;A competitor in a relay class is not on a team&quot;">​</a></h3><p><img src="'+q+'" alt="A competitor in a relay class is not on a team, opened to Vic Vale with class and club"></p><p><strong>What it means:</strong> the competitor is entered in a relay class but not on any team, so their leg can&#39;t count for anyone.</p><p><strong>How to fix it:</strong> add them to a team on the <strong>Teams</strong> page, or move them to an individual class.</p><h3 id="a-competitor-has-no-start-time-though-others-in-their-class-have-one" tabindex="-1">A competitor has no start time, though others in their class have one <a class="header-anchor" href="#a-competitor-has-no-start-time-though-others-in-their-class-have-one" aria-label="Permalink to &quot;A competitor has no start time, though others in their class have one&quot;">​</a></h3><p><img src="'+C+'" alt="No start time though others in their class have one, opened to Eve Eden and Ruby Stone with their classes"></p><p><strong>What it means:</strong> the rest of the class has start times and this competitor doesn&#39;t — usually a late entry added after the draw. (A class where <em>nobody</em> has a start time is a punching start, and isn&#39;t reported.)</p><p><strong>How to fix it:</strong> click the competitor and give them a start time, or let them punch the start. See <a href="./../event-setup/start-times#a-runner-with-no-start-time">A runner with no start time</a>.</p><h3 id="a-start-conflict" tabindex="-1">A start conflict <a class="header-anchor" href="#a-start-conflict" aria-label="Permalink to &quot;A start conflict&quot;">​</a></h3><p><img src="'+P+'" alt="Start conflicts, opened to Cal Cole and Dan Dale under 10:14:00, and Ann Able and Bea Baker under 10:52:00, each with class and course"></p><p><strong>What it means:</strong> competitors leave the start at the same time on the same course, or on courses that begin at the same control, so they can follow each other. They are listed under the time they share, with their class and course; a class mass start is listed as the class.</p><p><strong>How to fix it:</strong> often intended — a chasing start, or classes sent off together on purpose — and then nothing. Otherwise click a competitor and move their start time, or redraw. See <a href="./../event-setup/start-draw#lanes-that-share-a-first-control">Lanes that share a first control</a>.</p><h2 id="info" tabindex="-1">Info <a class="header-anchor" href="#info" aria-label="Permalink to &quot;Info&quot;">​</a></h2><p>Info never stops a start. Fix it when it suits you.</p><h3 id="a-class-has-nobody-entered" tabindex="-1">A class has nobody entered <a class="header-anchor" href="#a-class-has-nobody-entered" aria-label="Permalink to &quot;A class has nobody entered&quot;">​</a></h3><p><img src="'+W+'" alt="A class has nobody entered, opened to Juniors"></p><p><strong>What it means:</strong> nobody is in the class. Fine if late entries may come.</p><p><strong>How to fix it:</strong> leave it, or click it and delete it in <strong>Edit class</strong>.</p><h3 id="a-course-is-not-used-by-any-class" tabindex="-1">A course is not used by any class <a class="header-anchor" href="#a-course-is-not-used-by-any-class" aria-label="Permalink to &quot;A course is not used by any class&quot;">​</a></h3><p><img src="'+S+'" alt="A course is not used by any class, opened to Course 6"></p><p><strong>What it means:</strong> no class runs the course. Often a spare or a course left over from the course file.</p><p><strong>How to fix it:</strong> leave it, give it to a class, or click it and delete it in <strong>Edit course</strong>.</p><h3 id="a-competitor-has-only-a-given-or-a-family-name" tabindex="-1">A competitor has only a given or a family name <a class="header-anchor" href="#a-competitor-has-only-a-given-or-a-family-name" aria-label="Permalink to &quot;A competitor has only a given or a family name&quot;">​</a></h3><p><img src="'+T+'" alt="A competitor has only a given or a family name, opened to Kai in W21E"></p><p><strong>What it means:</strong> one half of the name is missing. Fine for a <a href="./../event-setup/competitors-clubs-teams#a-group-on-one-card">group on one card</a> or someone known by one name.</p><p><strong>How to fix it:</strong> click the competitor and fill in the other half, if there is one.</p><h3 id="a-competitor-has-no-club" tabindex="-1">A competitor has no club <a class="header-anchor" href="#a-competitor-has-no-club" aria-label="Permalink to &quot;A competitor has no club&quot;">​</a></h3><p><img src="'+I+'" alt="A competitor has no club, opened to Jamie Lee in M21E"></p><p><strong>What it means:</strong> the competitor has no club. Fine for a casual entrant; results show the club blank.</p><p><strong>How to fix it:</strong> click the competitor and choose their <strong>Club</strong>.</p><h3 id="a-competitor-shares-a-name-with-someone-in-another-club" tabindex="-1">A competitor shares a name with someone in another club <a class="header-anchor" href="#a-competitor-shares-a-name-with-someone-in-another-club" aria-label="Permalink to &quot;A competitor shares a name with someone in another club&quot;">​</a></h3><p><img src="'+H+'" alt="A competitor shares a name, opened to two Lee Chan entries with their classes and clubs"></p><p><strong>What it means:</strong> two competitors in different clubs have the same name. Common names are common, so it&#39;s usually two people; the clubs beside them are what tell them apart. It is worth a look when a club may have been entered wrongly.</p><p><strong>How to fix it:</strong> nothing, if they are two people. Otherwise click the entry that&#39;s wrong and fix its club, or delete it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./dashboard#starting-and-finishing">The event dashboard</a> — starting and finishing the event</li><li><a href="./../event-setup/pre-event-checklist">Pre-event checklist</a></li><li><a href="./resolving-issues">Resolving issues on the day</a></li></ul>',121)])])}const G=s(E,[["render",B]]);export{J as __pageData,G as default};
